import unittest
from candidate import strlen

class TestStrlen(unittest.TestCase):
    def test_strlen_empty_string(self):
        self.assertEqual(strlen(''), 0)

    def test_strlen_single_character(self):
        self.assertEqual(strlen('a'), 1)

    def test_strlen_three_characters(self):
        self.assertEqual(strlen('abc'), 3)

    def test_strlen_longer_string(self):
        self.assertEqual(strlen('hello world'), 11)

    def test_strlen_string_with_spaces(self):
        self.assertEqual(strlen('   '), 3)

    def test_strlen_string_with_tabs_and_newlines(self):
        self.assertEqual(strlen('\t\n'), 2)

    def test_strlen_unicode_string(self):
        self.assertEqual(strlen('héllo'), 5)

    def test_strlen_chinese_characters(self):
        self.assertEqual(strlen('你好世界'), 4)

    def test_strlen_emoji_string(self):
        self.assertEqual(strlen('🐍'), 1)

    def test_strlen_numeric_string(self):
        self.assertEqual(strlen('12345'), 5)

    def test_strlen_string_with_special_characters(self):
        self.assertEqual(strlen('!@#$%'), 5)

    def test_strlen_very_long_string(self):
        s = 'a' * 10000
        self.assertEqual(strlen(s), 10000)

    def test_strlen_returns_int_type(self):
        self.assertIsInstance(strlen('abc'), int)

    def test_strlen_none_input_raises_typeerror(self):
        with self.assertRaises(TypeError):
            strlen(None)

    def test_strlen_integer_input_raises_typeerror(self):
        with self.assertRaises(TypeError):
            strlen(123)

    def test_strlen_list_input_raises_typeerror(self):
        with self.assertRaises(TypeError):
            strlen(['a', 'b', 'c'])

    def test_strlen_tuple_input_raises_typeerror(self):
        with self.assertRaises(TypeError):
            strlen(('a', 'b'))

    def test_strlen_dict_input_raises_typeerror(self):
        with self.assertRaises(TypeError):
            strlen({'a': 1})

    def test_strlen_float_input_raises_typeerror(self):
        with self.assertRaises(TypeError):
            strlen(3.14)

    def test_strlen_bytes_input_raises_typeerror(self):
        with self.assertRaises(TypeError):
            strlen(b'abc')

    def test_strlen_none_multiple_calls(self):
        with self.assertRaises(TypeError):
            strlen(None)
        with self.assertRaises(TypeError):
            strlen(None)

if __name__ == '__main__':
    unittest.main()
